use super::prelude::*;

/// Counter sentinel scheme for Vambrace's one-shot "double the first
/// card-granted block each combat":
///   * `0`           — armed (no card has opened the doubling window yet),
///   * `-(card uid)` — window open for THAT specific card (C#
///     `TriggeringCard`); only that card's block keeps doubling,
///   * `1`           — used (`BlockGainedThisCombat == true`); never
///     doubles again this combat.
///
/// The pending state encodes the **triggering card's uid** (negated; card
/// uids are `NonZeroU32`, so the value is strictly `< 0` and never collides
/// with `ARMED` `0` or `USED` `1`). This is the load-bearing difference from
/// the prior single-`-1`-pending scheme: C# `Vambrace.ModifyBlockMultiplicative`
/// has the guard `if (TriggeringCard != null && TriggeringCard != cardSource)
/// return 1m;` — so a *different* card that gains block while the window is
/// still open (e.g. a nested auto-play, or a block-gaining card still
/// in-flight when its rider plays Fisticuffs) is NOT doubled. The old scheme
/// gated only on `counter <= 0` with no card identity, doubling such a second
/// card and over-granting its block 2× vs the game. `PaelsLegion` (the other
/// card-block doubler) has NO such guard in C# — it gates only on `Cooldown`
/// — so it keeps the identity-free counter and is unaffected.
const VAMBRACE_ARMED: i32 = 0;
const VAMBRACE_USED: i32 = 1;

/// Encode the pending doubling-window for triggering card `uid` (C#
/// `TriggeringCard`). Negated card uid → strictly `< 0`, distinct from
/// `VAMBRACE_ARMED`/`VAMBRACE_USED`.
fn vambrace_pending_for(uid: crate::CardUid) -> i32 {
    -(uid.get() as i32)
}

/// `Vambrace.before_combat_start` — reset the latch to armed
/// (`relic.counter = 0`). Mirrors C# `Vambrace.cs::BeforeCombatStart`
/// (`TriggeringCard = null; BlockGainedThisCombat = false`). Bead
/// `sts2-rs-6z05` (unblocked by the `BlockGainedCtx.card_source` infra
/// landed with `sts2-rs-ppabi`; replaces the prior inert `15y2` stub).
pub(crate) fn on_before_combat_start_vambrace(state: &mut CombatState) -> EffectResult {
    let Some(idx) = state
        .relics
        .iter()
        .position(|r| !r.is_melted && r.kind == crate::RelicKind::Vambrace)
    else {
        return EffectResult::NotImplemented;
    };
    state.relics[idx].counter = VAMBRACE_ARMED;
    EffectResult::Resolved
}

/// `Vambrace.modify_block_multiplicative` — double (`2×`) the player's
/// card-granted block while the one-shot is unused AND the block comes from
/// the card that opened the window. Mirrors C#
/// `Vambrace.cs::ModifyBlockMultiplicative` in full:
///   * `props.IsCardOrMonsterMove()` (`ctx.props` carries the `MOVE` flag),
///   * `cardSource != null` (`ctx.card_source.is_some()`),
///   * `TriggeringCard == null || TriggeringCard == cardSource` — the
///     **card-identity guard**: `counter == ARMED` (no window yet) OR
///     `counter == vambrace_pending_for(src)` (window open for THIS card),
///   * `target == Owner` (the player),
///   * `!BlockGainedThisCombat` (`counter != USED`).
/// Returns identity otherwise.
///
/// The card-identity guard is what stops a *different* card gaining block
/// while the window is open from being doubled — e.g. a block-gaining card
/// still in-flight whose rider plays Fisticuffs, which the old
/// `counter <= 0`-only gate over-doubled (block 2× vs the game).
///
/// The `MOVE`-flag gate is load-bearing (q6bix PLAYER_STATE cluster
/// `1db105`): power-fired block grants that happen to run *during* a
/// card-play — e.g. `FeelNoPainPower.AfterCardExhausted` while
/// `SecondWind` is exhausting the hand — call
/// `gain_block_player_unpowered`, which still picks up the play-pile top
/// as `ctx.card_source` even though C# passes `cardSource = null` there.
/// Those grants carry `ValueProp.Unpowered` (no `Move` flag), so C#'s
/// `IsCardOrMonsterMove()` is false and they are NOT doubled; matching
/// that here (rather than relying on `card_source` alone) keeps Vambrace
/// from doubling FeelNoPain's block on top of SecondWind's.
pub(crate) fn on_modify_block_multiplicative_vambrace(
    state: &CombatState,
    ctx: &BlockCtx,
) -> crate::hooks::DamageMul {
    let Some(src) = ctx.card_source else {
        return crate::hooks::DamageMul::ONE;
    };
    if !ctx.props.contains(ValueProps::MOVE) || !matches!(ctx.target, CreatureRef::Player) {
        return crate::hooks::DamageMul::ONE;
    }
    let counter = state
        .relics
        .iter()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::Vambrace)
        .map(|r| r.counter);
    match counter {
        Some(c) if c == VAMBRACE_ARMED || c == vambrace_pending_for(src) => {
            crate::hooks::DamageMul::new(2, 1)
        }
        _ => crate::hooks::DamageMul::ONE,
    }
}

/// `Vambrace.after_block_gained` — record the latest card to gain
/// card-sourced block as the triggering card, opening/keeping the doubling
/// window for it (`counter = vambrace_pending_for(src)`). Mirrors C#
/// `Vambrace.cs::AfterModifyingBlockAmount` setting `TriggeringCard =
/// cardSource` for any positive card-sourced block. Subsequent block gains
/// in the SAME card-play keep `counter == vambrace_pending_for(src)` and are
/// still doubled by [`on_modify_block_multiplicative_vambrace`]; a block
/// gain from a *different* card re-points the window to that card (matching
/// C#) but is itself NOT doubled (the multiplicative guard saw the old
/// triggering card). Once the one-shot has fired (`USED`) the latch is
/// sticky — C#'s `BlockGainedThisCombat` makes further `TriggeringCard`
/// updates moot, so we leave it untouched.
pub(crate) fn on_after_block_gained_vambrace(
    state: &mut CombatState,
    ctx: &BlockGainedCtx,
) -> EffectResult {
    let Some(src) = ctx.card_source else {
        return EffectResult::NotImplemented;
    };
    if !matches!(ctx.target, CreatureRef::Player) {
        return EffectResult::NotImplemented;
    }
    let Some(idx) = state
        .relics
        .iter()
        .position(|r| !r.is_melted && r.kind == crate::RelicKind::Vambrace)
    else {
        return EffectResult::NotImplemented;
    };
    if state.relics[idx].counter == VAMBRACE_USED {
        return EffectResult::NotImplemented;
    }
    state.relics[idx].counter = vambrace_pending_for(src);
    EffectResult::Resolved
}

/// `Vambrace.after_card_played` — when the card that opened the doubling
/// window finishes resolving, latch the one-shot used for the rest of the
